// GIVEN by the paper — do not change.
public class Laptop {
    private String maker;
    private int rate;

    public Laptop() {
        this("", 0);
    }

    public Laptop(String maker, int rate) {
        this.maker = maker;
        this.rate = rate;
    }

    public String getMaker() {
        return maker;
    }

    public void setMaker(String maker) {
        this.maker = maker;
    }

