public class SpecLaptop extends Laptop {
    private int ram;

    public SpecLaptop() {
        this("", 0, 0);
    }

    public SpecLaptop(String maker, int rate, int ram) {
        super(maker, rate);
        this.ram = ram;
    }

    @Override
    public String toString() {
        return super.toString() + ", " + ram;
    }

    public void setData() {
        setMaker("Spec_" + getMaker());
    }

    public int getValue() {
        return getRate() < 5 ? getRate() + ram : getRate() * ram;
    }
