 "extra": [
  "cham"
 ],
 "main": "KiemTra",
 "javaMin": 8,
 "timeoutMs": 10000,
 "loose": false,
 "lab211": false,
 "rules": [],
 "cases": [
  {
   "name": "structure and engine swap",
   "input": "1\n",
   "expected": "Car: class\nCar has a private Engine field: true\nCar exposes setHorsePower: false\nVios: vroom (107 hp) | hp 107\nVios: hum (150 hp, 42 kWh) | hp 150\n"
  }
 ]
};

const HERE = path.dirname(fileURLToPath(import.meta.url));
const args = process.argv.slice(2);
const SHOW = args.includes('--show');
const RECORD = args.includes('--record') ? args[args.indexOf('--record') + 1] : null;
const ONLY = args.includes('--case') ? Number(args[args.indexOf('--case') + 1]) : null;
